def experiment(inputs):
    import random
    trials = inputs.get('trials', [])
    results = []
    for trial in trials:
        vals = list(trial.get('values', []))
        vals.sort()
        results.append({
            'id': trial.get('id'),
            'sorted_values': vals
        })
    return {'trials': results}

